CREATE OR REPLACE PROCEDURE sp_test(
    para_ResID     IN NUMBER,
    para_ResName   IN VARCHAR2,
    para_Address   IN VARCHAR2,
    para_StuID     IN NUMBER,
    para_LName     IN VARCHAR2,
    para_ResTypeID IN NUMBER
) AS
    v_rest_count NUMBER;
BEGIN
    SELECT COUNT(*) INTO v_rest_count FROM "Restaurant" WHERE "ResID" = para_ResID;
    IF para_ResID <> 0 AND v_rest_count = 0 THEN
        UPDATE "Restaurant_Type"
           SET "ResTypeID" = "ResTypeID" + 10
         WHERE "ResTypeID" >= para_ResTypeID - 19;
        UPDATE "Type_Of_Restaurant"
           SET "ResTypeID" = "ResTypeID" + 10
         WHERE "ResTypeID" >= para_ResTypeID - 19;
    ELSE
        IF para_ResName LIKE '%' THEN
            DELETE FROM "Type_Of_Restaurant"
             WHERE "ResID" IN (SELECT "ResID" FROM "Restaurant"
                                WHERE "ResName" LIKE para_ResName AND "Address" = para_Address);
            DELETE FROM "Restaurant"
             WHERE "ResName" LIKE para_ResName AND "Address" = para_Address;
        ELSIF para_Address LIKE 'PENDING%' THEN
            UPDATE "Restaurant"
               SET "Address" = 'PENDING'
             WHERE "ResID" <> para_ResID;
        ELSE
            UPDATE "Restaurant"
               SET "ResName" = para_Address
             WHERE "ResID" <> para_ResID;
        END IF;
    END IF;
END sp_test;

CREATE OR REPLACE PROCEDURE sp_test(
    para_ResID     IN NUMBER,
    para_ResName   IN VARCHAR2,
    para_Address   IN VARCHAR2,
    para_StuID     IN NUMBER,
    para_LName     IN VARCHAR2,
    para_ResTypeID IN NUMBER
) AS
    v_rest_count NUMBER;
BEGIN
    SELECT COUNT(*) INTO v_rest_count FROM "Restaurant" WHERE "ResID" = para_ResID;
    IF para_ResID <> 0 AND v_rest_count = 0 THEN
        UPDATE "Restaurant_Type"
           SET "ResTypeID" = "ResTypeID" + 10
         WHERE "ResTypeID" >= para_ResTypeID - 19;
        UPDATE "Type_Of_Restaurant"
           SET "ResTypeID" = "ResTypeID" + 10
         WHERE "ResTypeID" >= para_ResTypeID - 19;
    ELSE
        IF INSTR(para_ResName, '%') > 0 THEN
            DELETE FROM "Type_Of_Restaurant"
             WHERE "ResID" IN (SELECT "ResID" FROM "Restaurant"
                                WHERE "ResName" LIKE para_ResName AND "Address" = para_Address);
            DELETE FROM "Restaurant"
             WHERE "ResName" LIKE para_ResName AND "Address" = para_Address;
        ELSIF INSTR(para_Address, 'PENDING') = 1 THEN
            UPDATE "Restaurant"
               SET "Address" = 'PENDING'
             WHERE "ResID" <> para_ResID;
        ELSE
            UPDATE "Restaurant"
               SET "ResName" = para_Address
             WHERE "ResID" <> para_ResID;
        END IF;
    END IF;
END sp_test;
